<template>
  <view class="club-page detail-page">
    <view class="brand-poster detail-hero"><view><view class="eyebrow">ORDER DETAIL</view><view class="title">陪玩订单详情</view><view class="sub">{{ orderNo }}</view></view><view v-if="orderInfo" class="club-status" :class="statusClass(orderInfo.status)">{{ orderInfo.status }}</view></view>
    <view v-if="loading" class="club-empty">加载中...</view>

    <view v-if="orderInfo" class="club-card">
      <view class="club-card__hd"><text class="club-card__title">服务信息</text><button class="tiny-link" :loading="refreshing" :disabled="refreshing" @tap="handleManualRefresh">{{ refreshing ? '刷新中' : '刷新' }}</button></view>
      <view class="club-card__bd">
        <view v-if="orderInfo.boss_name" class="info-row"><text>老板</text><text>{{ orderInfo.boss_name }}</text></view><view class="info-row"><text>套餐</text><text>{{ orderInfo.package_name }}</text></view><view v-if="orderInfo.addon_name" class="info-row"><text>附加项</text><text>{{ orderInfo.addon_name }}</text></view><view v-if="orderInfo.game_id" class="info-row"><text>游戏ID/队伍码</text><text class="copyable" @tap="copyText(orderInfo.game_id)">{{ orderInfo.game_id }}</text></view><view v-if="orderInfo.kook_room_number" class="info-row"><text>KOOK房间号</text><text class="copyable" @tap="copyText(orderInfo.kook_room_number)">{{ orderInfo.kook_room_number }}</text></view><view class="info-row"><text>主订单钻石</text><text class="amount">💎{{ orderDiamonds }}</text></view><view class="info-row"><text>累计服务时长</text><text class="duration">{{ totalBookedHoursText }}</text></view><view v-if="orderInfo.status === '待接单'" class="info-row"><text>等待时间</text><text>{{ waitTime }}</text></view><view v-if="orderInfo.status === '待支付'" class="info-row"><text>当前阶段</text><text>{{ serverConfirming ? '微信支付结果核验中' : '等待老板付款' }}</text></view><view v-if="orderInfo.status === '待开打'" class="info-row"><text>当前阶段</text><text class="duration">老板已付款，可开打</text></view><view v-if="orderInfo.status === '进行中'" class="info-row"><text>已进行</text><text class="duration">{{ duration }}</text></view><view v-if="orderInfo.duration_minutes" class="info-row"><text>实际服务</text><text>{{ orderInfo.duration_minutes }} 分钟</text></view>
      </view>
    </view>

    <view v-if="orderInfo?.status === '待支付'" class="club-card payment-wait-card" :class="{ 'payment-wait-card--confirming': serverConfirming }"><view class="club-card__hd"><view><text class="club-card__title">{{ serverConfirming ? '正在核验老板支付结果' : '等待老板付款' }}</text><text class="card-sub">{{ serverConfirming ? '支付入口已关闭，阵容暂时继续保留' : '老板有10分钟完成支付，期间请保持在线' }}</text></view><text class="countdown-chip">{{ paymentCountdown }}</text></view><view class="message-box"><text>{{ serverConfirming ? '系统正在向微信确认是否已经扣款。' : '当前阵容已经为老板保留。' }}</text><text>{{ serverConfirming ? '核验结束前无需进入老板房间，也不会因为等待产生迟到记录。' : '付款成功后页面会自动变为“待开打”，届时才开始计算进入房间的时间。' }}</text></view></view>
    <view v-if="timeoutCancelled" class="club-card release-card"><view class="club-card__hd"><text class="club-card__title">订单已由系统释放</text><text class="release-chip">不计责任</text></view><view class="message-box"><text>老板未在规定时间内完成付款，订单已经自动取消。</text><text>本次不会计入你的取消、迟到或处罚记录，可以返回大厅继续接单。</text></view></view>

    <view v-if="orderInfo && myOrderPlayer && roomEntryVisible" class="club-card room-entry-card" :class="`room-entry-${roomJoinStatus}`"><view class="club-card__hd"><view><text class="club-card__title">进入老板房间</text><text class="card-sub">老板付款后10分钟内进入房间并主动确认</text></view><text class="room-entry-chip">{{ roomJoinStatusText }}</text></view><view v-if="roomJoinStatus === 'pending'" class="room-entry-countdown"><text>剩余时间</text><text>{{ roomJoinCountdown }}</text></view><view v-else-if="roomJoinStatus === 'overdue'" class="room-entry-warning"><text>已经超过10分钟</text><text>请尽快进入并确认。本次记录交由管理员核实。</text></view><view v-else-if="roomJoinStatus === 'late_confirmed'" class="room-entry-warning"><text>已在超时后确认</text><text>系统已保留记录，后续由管理员结合实际情况核实。</text></view><view v-else class="room-entry-success"><text>已完成进入确认</text><text v-if="myOrderPlayer.room_join_confirmed_at">确认时间：{{ formatRoomTime(myOrderPlayer.room_join_confirmed_at) }}</text></view><button v-if="canConfirmRoomEntry" class="room-entry-btn" :disabled="confirmingRoom" @tap="handleConfirmRoomEntry">{{ confirmingRoom ? '确认中...' : '我已进入老板房间' }}</button><text class="room-entry-tip">请仅在实际进入游戏或KOOK房间后点击，老板端会同步看到状态。</text></view>

    <view v-if="canCancelOrder" class="club-card cancel-policy-card"><view class="club-card__hd"><text class="club-card__title">取消接单规则</text><text :class="noFaultEligible ? 'release-chip' : 'cancel-policy-chip'">{{ noFaultEligible ? '可无责退出' : '按拒单处理' }}</text></view><template v-if="noFaultEligible"><text>你接单后等待组队已超过15分钟，本次退出不计拒单。</text><text>不会暂停接单、不会罚款，也不会消耗当天免罚机会；退出后仍不能重新抢回同一订单。</text></template><template v-else><text>取消后将暂停接单，暂停时长等于本单累计服务时长。</text><text>{{ orderInfo?.status === '进行中' ? '服务中退出按近3天一次免罚机会计算。' : '进队前取消按每天一次免罚机会计算。' }}</text><text>超过免罚次数后按人民币20 / 50 / 100元等值鱼干阶梯处罚，余额不足会形成欠款并冻结接单资格。</text></template></view>

    <view v-if="orderInfo && (renewalCount || orderInfo.pending_renewal_order_no)" class="club-card renewal-card"><view class="club-card__hd"><text class="club-card__title">续单信息</text><text class="renewal-badge">已续 {{ renewalCount }} 次</text></view><view class="renewal-grid"><view><text>原时长</text><text>{{ formatHours(orderInfo.booked_hours) }}</text></view><view><text>续单时长</text><text>{{ formatHours(orderInfo.renewal_booked_hours) }}</text></view><view><text>累计时长</text><text>{{ totalBookedHoursText }}</text></view></view><view v-if="orderInfo.pending_renewal_order_no" class="renewal-pending"><text>老板有一笔续单等待付款</text><text>付款完成后新增时长会自动计入本单；待支付期间暂不能完成服务。</text></view><view v-if="paidRenewals.length" class="renewal-list"><view v-for="item in paidRenewals" :key="item.order_no" class="renewal-row"><text>第{{ item.renewal_index }}次续单 · +{{ formatHours(item.booked_hours) }}</text><text>已支付 💎{{ renewalDiamonds(item) }}</text></view></view></view>

    <view v-if="orderInfo && canEditKookRoom" class="club-card kook-card"><view class="club-card__hd"><text class="club-card__title">KOOK 房间号</text><text class="room-status" :class="{ 'room-status--warn': !orderInfo.kook_room_number }">{{ orderInfo.kook_room_number ? '已填写' : '待填写' }}</text></view><view class="kook-desc">多个陪玩接同一单时，只要任意一位填写，整张订单都会统一使用这个房间号。</view><view class="kook-input-row"><input v-model="roomInput" class="kook-input" placeholder="请输入 KOOK 房间号，例如 TC8888-01" maxlength="100" @focus="roomFocused = true" @blur="roomFocused = false" /><button class="save-room-btn" :disabled="savingRoom" @tap="saveKookRoom">{{ savingRoom ? '保存中' : (orderInfo.kook_room_number ? '更新' : '保存') }}</button></view><view v-if="orderInfo.kook_room_updated_at" class="kook-tip">最近更新时间：{{ formatRoomTime(orderInfo.kook_room_updated_at) }}</view><view v-else class="kook-tip">老板付款后，填写房间号即可确认开打。</view></view>

    <view v-if="orderInfo?.boss_note" class="club-card note-card"><text>老板备注</text><text>{{ orderInfo.boss_note }}</text></view>
    <view v-if="orderInfo" class="club-card"><view class="club-card__hd"><text class="club-card__title">队伍陪玩</text><text class="club-pill">{{ orderInfo.players?.length || 0 }}/{{ orderInfo.required_players }}</text></view><view class="club-card__bd player-stack"><view v-for="playerItem in orderInfo.players" :key="playerItem.id" class="player-row"><text class="avatar">{{ playerItem.name?.[0] }}</text><view class="player-main"><text>{{ playerItem.name }}</text><text>{{ playerItem.type_name }} · {{ playerItem.room_join_status_text || playerItem.status || '已接单' }}</text></view><text v-if="playerItem.id === player?.id" class="me-tag">我</text></view></view></view>

    <view class="footer-actions"><button class="club-btn club-btn--ghost" @tap="backToRoute('/pages/player/grab/index')">大厅</button><button v-if="canCancelOrder" class="club-btn club-btn--danger" :disabled="canceling" @tap="handleCancelOrder">{{ canceling ? '处理中...' : cancelButtonText }}</button><button v-if="orderInfo?.status === '待开打'" class="club-btn" :disabled="starting" @tap="handleStartTimer">{{ starting ? '开打中...' : '确认开打' }}</button><button v-if="orderInfo?.status === '进行中' && orderInfo?.timer_started_at && !orderInfo?.is_paused" class="club-btn club-btn--warn" @tap="handlePause">暂停</button><button v-if="orderInfo?.status === '进行中' && orderInfo?.is_paused" class="club-btn" @tap="handleResume">继续</button><button v-if="orderInfo?.status === '进行中'" class="club-btn" :disabled="completing" @tap="handleComplete">完成</button><button v-if="orderInfo?.status === '待支付'" class="club-btn club-btn--ghost" @tap="toast(serverConfirming ? '系统正在核验微信支付结果' : '等待老板在倒计时内完成付款')">{{ serverConfirming ? '支付核验中' : '等待付款' }}</button><button v-if="timeoutCancelled" class="club-btn" @tap="backToRoute('/pages/player/grab/index')">继续接单</button></view>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { completeOrder, confirmPlayerRoomEntry, getPlayerOrder, pausePlayerOrder, resumePlayerOrder, setPlayerOrderKookRoom, startTimer } from '@/api/player'
import { cancelPlayerOrder, getPlayerCancellationPreview, type PlayerCancellationPreview } from '@/api/orderCancellation'
import { diamondsFrom, formatDiamonds } from '@/utils/diamonds'
import { formatDuration } from '@/utils/format'
import { getStorage } from '@/utils/storage'
import { confirm, getErrorMessage, success, toast } from '@/utils/feedback'
import { goMain, replace, backToRoute } from '@/utils/nav'
import { isApprovedPlayer } from '@/utils/client'

const orderNo = ref(''); const orderInfo = ref<any>(null); const player = ref<any>(null); const loading = ref(true); const refreshing = ref(false); const starting = ref(false); const completing = ref(false); const canceling = ref(false); const confirmingRoom = ref(false); const savingRoom = ref(false); const roomInput = ref(''); const roomFocused = ref(false); const duration = ref('00:00:00'); const waitTime = ref(''); const now = ref(Date.now())
let refreshTimer: ReturnType<typeof setInterval> | null = null; let durationTimer: ReturnType<typeof setInterval> | null = null; let prevPlayerCount = 0; let previousStatus = ''
const canEditKookRoom = computed(() => Boolean(orderInfo.value && ['待开打', '进行中'].includes(orderInfo.value.status)))
const renewalCount = computed(() => Number(orderInfo.value?.renewal_count || 0)); const paidRenewals = computed(() => (orderInfo.value?.renewals || []).filter((item: any) => item.paid)); const totalBookedHoursText = computed(() => formatHours(orderInfo.value?.total_booked_hours ?? orderInfo.value?.booked_hours ?? 0)); const myOrderPlayer = computed(() => (orderInfo.value?.players || []).find((item: any) => Number(item.id) === Number(player.value?.id)) || null); const roomEntryVisible = computed(() => Boolean(['待开打', '进行中', '已完成'].includes(orderInfo.value?.status))); const canCancelOrder = computed(() => Boolean(myOrderPlayer.value && ['待接单', '待支付', '待开打', '进行中'].includes(orderInfo.value?.status))); const cancelButtonText = computed(() => noFaultEligible.value ? '无责退出' : (orderInfo.value?.status === '进行中' ? '中途退出' : '取消接单')); const paymentPhase = computed(() => String(orderInfo.value?.payment_phase || 'inactive')); const serverConfirming = computed(() => orderInfo.value?.status === '待支付' && paymentPhase.value === 'confirming'); const timeoutCancelled = computed(() => Boolean(orderInfo.value?.status === '已取消' && /10分钟|自动取消|未完成支付/.test(String(orderInfo.value?.cancel_reason || ''))))
const noFaultEligible = computed(() => { const relation = myOrderPlayer.value; if (!relation?.grab_time || orderInfo.value?.paid || !['待接单', '待支付'].includes(orderInfo.value?.status)) return false; return now.value - new Date(relation.grab_time).getTime() >= 15 * 60 * 1000 })
const orderDiamonds = computed(() => { try { return formatDiamonds(diamondsFrom(orderInfo.value?.total_amount_diamonds ?? orderInfo.value?.total_price_per_hour_diamonds, orderInfo.value?.total_amount || orderInfo.value?.total_price_per_hour || 0)) } catch { return '--' } })
const paymentCountdown = computed(() => { const deadline = serverConfirming.value ? orderInfo.value?.payment_confirmation_deadline_at : orderInfo.value?.payment_deadline_at; if (!deadline) return '--:--'; return formatCountdown(Math.max(0, Math.floor((new Date(deadline).getTime() - now.value) / 1000))) })
const roomJoinStatus = computed(() => String(myOrderPlayer.value?.room_join_status || 'pending')); const roomJoinStatusText = computed(() => myOrderPlayer.value?.room_join_status_text || ({ pending: '等待进入', confirmed: '按时进入', late_confirmed: '超时后进入', overdue: '已超时待核实', waived: '管理员已免除' } as Record<string, string>)[roomJoinStatus.value] || '等待进入'); const roomJoinCountdown = computed(() => { const deadline = myOrderPlayer.value?.room_join_deadline; if (!deadline) return '--:--'; const seconds = Math.max(0, Math.floor((new Date(deadline).getTime() - now.value) / 1000)); return seconds ? formatCountdown(seconds) : '已超时' }); const canConfirmRoomEntry = computed(() => Boolean(roomEntryVisible.value && myOrderPlayer.value?.can_confirm_room_join && !['已完成', '已取消'].includes(orderInfo.value?.status) && ['pending', 'overdue'].includes(roomJoinStatus.value)))
function renewalDiamonds(item: any) { try { return formatDiamonds(diamondsFrom(item.total_amount_diamonds, item.total_amount || 0)) } catch { return '--' } }
function formatHours(value: number | string) { const hours = Number(value || 0); return Number.isInteger(hours) ? `${hours}小时` : `${hours.toFixed(1)}小时` }
function formatCountdown(value: number) { const seconds = Math.max(0, Math.floor(Number(value || 0))); return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}` }
function statusClass(status: string) { return { 'club-status--wait': status === '待接单', 'club-status--pay': status === '待支付', 'club-status--ready': status === '待开打', 'club-status--run': status === '进行中', 'club-status--done': status === '已完成', 'club-status--cancel': status === '已取消' } }
function formatRoomTime(input: string) { if (!input) return '-'; const date = new Date(input); return `${date.getMonth() + 1}-${date.getDate()} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}` }
function updateDuration() { now.value = Date.now(); if (!orderInfo.value) return; if (orderInfo.value.timer_started_at) { const start = new Date(orderInfo.value.timer_started_at).getTime(); const end = orderInfo.value.end_time ? new Date(orderInfo.value.end_time).getTime() : orderInfo.value.is_paused && orderInfo.value.last_paused_at ? new Date(orderInfo.value.last_paused_at).getTime() : now.value; duration.value = formatDuration(Math.max(0, Math.floor((end - start) / 1000) - (orderInfo.value.paused_duration || 0))) } else if (orderInfo.value.status === '待开打') duration.value = '等待开打'; if (orderInfo.value.status === '待接单' && orderInfo.value.created_at) { const diffSec = Math.floor((now.value - new Date(orderInfo.value.created_at).getTime()) / 1000); waitTime.value = `等待 ${Math.floor(diffSec / 60)}:${String(diffSec % 60).padStart(2, '0')}` } else waitTime.value = '' }
async function fetchOrder() { try { const res = await getPlayerOrder(orderNo.value); const newCount = res.players?.length || 0; if (newCount > prevPlayerCount && prevPlayerCount > 0) toast('有陪玩就位'); prevPlayerCount = newCount; if (previousStatus === '待支付' && res.status === '待开打') success('老板已付款，可以准备进入房间'); if (previousStatus === '待支付' && res.status === '已取消' && /10分钟|自动取消|未完成支付/.test(String(res.cancel_reason || ''))) toast('老板未完成付款，订单已由系统释放'); previousStatus = res.status; orderInfo.value = res; if (!roomFocused.value) roomInput.value = res.kook_room_number || ''; updateDuration(); return true } catch (error) { toast(getErrorMessage(error, '订单刷新失败')); return false } finally { loading.value = false } }
async function handleManualRefresh() { if (refreshing.value) return; refreshing.value = true; try { if (await fetchOrder()) success('刷新成功') } finally { refreshing.value = false } }
async function handleConfirmRoomEntry() { if (!canConfirmRoomEntry.value || confirmingRoom.value) return; const message = roomJoinStatus.value === 'overdue' ? '当前已超过10分钟。请确认你已经实际进入老板房间，系统会记录为超时后进入并交由管理员核实。' : '请确认你已经实际进入老板的游戏或KOOK房间。确认后老板端会同步显示。'; if (!(await confirm(message, '确认进入房间'))) return; confirmingRoom.value = true; try { const result = await confirmPlayerRoomEntry(orderNo.value); success(result.message); await fetchOrder() } catch (error) { toast(getErrorMessage(error, '进入房间确认失败')) } finally { confirmingRoom.value = false } }
function promptCancelReason(preview: PlayerCancellationPreview): Promise<string | null> { const content = preview.no_fault ? `无责退出\n原因：${preview.no_fault_reason || '匹配等待超过15分钟'}\n不会暂停接单、罚款或消耗免罚机会。\n订单处理：${preview.replacement_text}\n\n请填写退出原因。` : `${preview.stage_text}\n暂停接单：${formatHours(preview.booked_hours)}\n${preview.used_free_chance ? '本次使用免罚机会，不扣罚款' : `本次罚款 ¥${Number(preview.fine_rmb).toFixed(0)}（${Number(preview.fine_fish).toFixed(0)}鱼干）`}\n订单处理：${preview.replacement_text}\n\n请填写真实取消原因。`; return new Promise(resolve => { uni.showModal({ title: preview.no_fault ? '确认无责退出' : '确认取消接单', content, editable: true, placeholderText: '请输入取消原因（至少2个字）', confirmText: preview.no_fault ? '确认退出' : '确认取消', confirmColor: '#c83d3d', success: (result: any) => { if (!result.confirm) return resolve(null); const reason = String(result.content || '').trim(); if (reason.length < 2) { toast('请填写至少2个字的取消原因'); return resolve(null) }; resolve(reason) }, fail: () => resolve(null) }) }) }
async function handleCancelOrder() { if (!canCancelOrder.value || canceling.value) return; canceling.value = true; try { const preview = await getPlayerCancellationPreview(orderNo.value); const reason = await promptCancelReason(preview); if (!reason) return; const result = await cancelPlayerOrder(orderNo.value, reason); stopTimers(); const debtText = Number(result.debt_fish || 0) > 0 ? `，另有${Number(result.debt_fish).toFixed(0)}鱼干欠款待补` : ''; success(result.no_fault ? '已无责退出，可继续接其他订单' : `已取消接单${debtText}`); replace('/pages/player/grab/index') } catch (error) { toast(getErrorMessage(error, '取消接单失败')) } finally { canceling.value = false } }
async function saveKookRoom() { const value = roomInput.value.trim(); if (!value) { toast('请填写 KOOK 房间号'); return false }; savingRoom.value = true; try { const res = await setPlayerOrderKookRoom(orderNo.value, value); if (orderInfo.value) { orderInfo.value.kook_room_number = res.kook_room_number; orderInfo.value.kook_room_updated_at = new Date().toISOString() }; roomInput.value = res.kook_room_number; success('KOOK 房间号已保存'); await fetchOrder(); return true } catch (error) { toast(getErrorMessage(error, '房间号保存失败')); return false } finally { savingRoom.value = false } }
async function ensureKookRoom() { if (orderInfo.value?.kook_room_number) return true; if (roomInput.value.trim()) return saveKookRoom(); toast('请先填写 KOOK 房间号'); return false }
async function handleStartTimer() { if (!(await ensureKookRoom())) return; if (!(await confirm('老板已完成付款，确定现在开打并开始计时吗？', '确认开打'))) return; starting.value = true; try { await startTimer(orderNo.value, player.value.id); success('已开打，计时开始'); await fetchOrder() } catch (error) { toast(getErrorMessage(error, '开打失败')) } finally { starting.value = false } }
async function handlePause() { try { await pausePlayerOrder(orderNo.value); success('计时已暂停'); await fetchOrder() } catch (error) { toast(getErrorMessage(error, '暂停失败')) } }
async function handleResume() { try { await resumePlayerOrder(orderNo.value); success('计时已继续'); await fetchOrder() } catch (error) { toast(getErrorMessage(error, '继续失败')) } }
async function handleComplete() { if (!(await ensureKookRoom())) return; if (orderInfo.value?.pending_renewal_order_no) { toast('老板还有一笔续单待支付，暂不能完成服务'); return }; if (!(await confirm(`确定要标记订单完成吗？当前累计服务时长为${totalBookedHoursText.value}。`))) return; completing.value = true; try { await completeOrder(orderNo.value, player.value.id); success('已标记完成'); await fetchOrder() } catch (error) { toast(getErrorMessage(error, '操作失败')) } finally { completing.value = false } }
function copyText(text: string) { uni.setClipboardData({ data: text, success: () => success('已复制') }) }
function stopTimers() { if (refreshTimer) clearInterval(refreshTimer); if (durationTimer) clearInterval(durationTimer); refreshTimer = null; durationTimer = null }
onLoad(query => { orderNo.value = String(query?.orderNo || '') })
onMounted(async () => { if (!(await isApprovedPlayer())) { toast('请先成为陪玩师'); replace('/pages/player/apply/index'); return }; const token = getStorage<string>('token'); const playerInfo = getStorage<any>('player'); if (!token) { replace('/pages/client/login/index'); return }; if (!playerInfo) { toast('陪玩师信息未同步，请刷新个人中心'); goMain('profile'); return }; player.value = playerInfo; await fetchOrder(); refreshTimer = setInterval(fetchOrder, 5000); durationTimer = setInterval(updateDuration, 1000) })
onUnmounted(stopTimers)
</script>

